WITH q AS (SELECT r.table_id,r.reservation_start_at,r.reservation_end_at,c.full_name AS guest_name FROM shioricafe_schema.reservation r LEFT JOIN shioricafe_schema.customer c ON r.customer_id=c.customer_id WHERE r.status='Confirmed' AND TIMESTAMPTZ '2026-11-07T01:49:15.8173896+08:00'>=r.reservation_start_at AND TIMESTAMPTZ '2026-11-07T01:49:15.8173896+08:00'<r.reservation_end_at) SELECT jsonb_build_object('rows',count(*),'md5',md5(COALESCE(string_agg(to_jsonb(q)::text,E'\n' ORDER BY to_jsonb(q)::text),''))) FROM q;
